import{_ as o,o as r,c as e,a2 as d}from"./chunks/framework.CnHmQiA8.js";const u=JSON.parse('{"title":"插图与图像处理","description":"","frontmatter":{"title":"插图与图像处理","outline":[2,3]},"headers":[],"relativePath":"guide/images.md","filePath":"guide/images.md","lastUpdated":1795437342000}'),a={name:"guide/images.md"};function s(l,t,n,i,c,g){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="插图与图像处理" tabindex="-1">插图与图像处理 <a class="header-anchor" href="#插图与图像处理" aria-label="Permalink to &quot;插图与图像处理&quot;">​</a></h1><p>针对老师日常最常遇到的试卷截图发灰、插图与文字混排、扫描图模糊以及图片选项对齐问题，软件内置了全套本地插图定位与图像增强工具。</p><h2 id="_1-插图位置与预览交互" tabindex="-1">1. 插图位置与预览交互 <a class="header-anchor" href="#_1-插图位置与预览交互" aria-label="Permalink to &quot;1. 插图位置与预览交互&quot;">​</a></h2><h3 id="灵活的排版位置" tabindex="-1">灵活的排版位置 <a class="header-anchor" href="#灵活的排版位置" aria-label="Permalink to &quot;灵活的排版位置&quot;">​</a></h3><ul><li><strong>题目的图</strong>：支持放在 <code>题干下方</code>、<code>题干下方（居中）</code>、<code>题干右侧</code>、<code>题干下方位于选项 / 小问右侧</code>、<code>某个小问下方</code>、<code>全部题目文字下方</code> 或 <code>自由位置</code>。当选择题右侧有图时，每行 2 项或 4 项的选项会自动根据图片宽度调整间距并与图片同行排列。</li><li><strong>知识点插图 / 答案插图 / 解析插图</strong>：支持 <code>某段之后</code>、<code>某段之后（居中）</code>、<code>某段右侧</code> 或 <code>自由位置</code>。其中答案插图与解析插图在题目属性栏 <strong>仅教师版</strong> 页添加，只出现在教师版中。</li><li><strong>独立成段图片的转换</strong>：从网页或某些文档粘贴进来、在正文中单独成段的图片，属性面板会给出提示，点击 <strong>转为插图</strong> 即可纳入插图栏统一调节位置与大小。</li></ul><h3 id="预览区双向定位与直接拖拽" tabindex="-1">预览区双向定位与直接拖拽 <a class="header-anchor" href="#预览区双向定位与直接拖拽" aria-label="Permalink to &quot;预览区双向定位与直接拖拽&quot;">​</a></h3><ul><li><strong>双向定位</strong>：左键单击预览中的插图，右侧属性栏会自动跳转到该图的设置项；反之，在属性栏中单击插图缩略图，中间预览也会滚动到对应图片并短暂高亮。</li><li><strong>拖拽缩放与移动</strong>：选中所属题目或知识点后，拖动预览中图片右下角即可等比缩放；位于右侧环绕的图支持上下拖动微调，“自由位置”的图可任意拖动且文字自动绕排。</li></ul><h3 id="选择题的图片选项" tabindex="-1">选择题的图片选项 <a class="header-anchor" href="#选择题的图片选项" aria-label="Permalink to &quot;选择题的图片选项&quot;">​</a></h3><p>当选择题选项本身是图片时：</p><ul><li>在预览中拖动单个选项图片右下角只缩放这一张；按住 <code>Shift</code> 拖动则全部选项图一起等比缩放。</li><li>在属性面板 <strong>选项图片</strong> 分组中，可逐张设置宽度，或一键 <strong>全部缩小 / 放大 10%</strong>、<strong>以某个选项为准统一大小</strong>。图片调小后，选项会自动重新排为每行 2 项或 4 项。</li></ul><h2 id="_2-添加插图与自动框选" tabindex="-1">2. 添加插图与自动框选 <a class="header-anchor" href="#_2-添加插图与自动框选" aria-label="Permalink to &quot;2. 添加插图与自动框选&quot;">​</a></h2><p>在属性栏点击 <strong>添加题图 / 答案插图 / 解析插图 / 插图 / 背景配图</strong>，会打开与“从图片导入”相同的插图窗口：</p><ol><li>选择图片文件、拖入图片或按 <code>Ctrl+V</code> 粘贴截图。</li><li>软件在本地自动识别并框选其中的插图（自动避开文字行、答题括号与边框）；若想补充框选，直接在图上拖一个框即可自动收紧到图形边缘；不需要的框可直接删除或拖四角微调。</li><li>未框选任何框时默认整张添加；存在框选时按阅读顺序批量添加。</li></ol><h2 id="_3-图像变清晰、去白底与调色" tabindex="-1">3. 图像变清晰、去白底与调色 <a class="header-anchor" href="#_3-图像变清晰、去白底与调色" aria-label="Permalink to &quot;3. 图像变清晰、去白底与调色&quot;">​</a></h2><p>右键点击预览中的插图，或在属性栏的插图操作按钮中，都可以随时对当前图片做无损调优（全部支持 <code>Ctrl+Z</code> 撤销）：</p><table tabindex="0"><thead><tr><th>功能</th><th>适用场景</th><th>效果说明</th></tr></thead><tbody><tr><td><strong>变清晰</strong></td><td>低分辨率截图、教辅小图</td><td>清理灰底与杂点后，对小尺寸图片执行 FSRCNN ×3 超分放大，不改变原图几何结构与文字内容（导入窗口默认开启，支持点击对比处理前后）</td></tr><tr><td><strong>去白底</strong></td><td>带浅色/白色底色的插图</td><td>将白色背景转为透明，彩色与深色线条保留实色</td></tr><tr><td><strong>一键加深</strong></td><td>扫描件、拍照图片偏淡发灰</td><td>自动校准黑白场对比度，让偏灰线条变清晰同时保留阴影层次</td></tr><tr><td><strong>手动调色…</strong></td><td>需要精细修图</td><td>并排对照原图与预览，实时调节亮度、对比度与饱和度（饱和度拉到最左即为纯黑白）</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">批量处理全卷插图</p><p>点击左侧大纲顶部的 <strong>批量处理插图…</strong>，可以一次浏览全卷的所有插图（含题图、答案/解析插图、知识点插图与综合题配图），勾选多张一次性执行 <strong>变清晰</strong>、<strong>去白底</strong> 或 <strong>一键加深</strong>。</p></div><h2 id="_4-workbuddy-重绘为-svg-矢量图-可选" tabindex="-1">4. WorkBuddy 重绘为 SVG 矢量图（可选） <a class="header-anchor" href="#_4-workbuddy-重绘为-svg-矢量图-可选" aria-label="Permalink to &quot;4. WorkBuddy 重绘为 SVG 矢量图（可选）&quot;">​</a></h2><p>对于清晰度太差或线条破损严重的示意图，还可以借助 WorkBuddy 生成可无限放大的 SVG 矢量图：</p><ol><li>在“从图片导入”窗口勾选框左下角的 <strong>重绘</strong> 后点击 <strong>让 WorkBuddy 重绘插图</strong>，或在编辑界面的批量处理 / 右键快捷栏点击 <strong>WorkBuddy 重绘</strong>。</li><li>到 WorkBuddy 中输入 <code>重绘插图</code>，收到的结果会在框上标出 <code>SVG</code>。</li><li>软件会并排展示 <strong>原图</strong> 与 <strong>SVG 重绘结果</strong>，由你逐张核对确认后决定保留原图还是替换为 SVG（导出 Word 时自动栅格化保持兼容）。</li></ol><div class="warning custom-block"><p class="custom-block-title">注意核对细节</p><p>AI 重绘不能保证 100% 还原坐标刻度、箭头方向或字母标注，建议每一张都与原图并排比对后再点击应用。</p></div>',21)])])}const p=o(a,[["render",s]]);export{u as __pageData,p as default};
